 launchAircraft(id,x,y){const base=this.units.find(u=>u.id===id&&!u.dead&&!u.landed);if(!base||!['airbase','carrier'].includes(base.type)||!['fighter','bomber'].includes(base.mode))return {ok:false,reason:'Select an airbase or carrier in an aircraft launch state.'};if(this.phase>3)return {ok:false,reason:'Aircraft launch is available at DEFCON 3.'};if(base.stateTimer>0||base.cooldown>0)return {ok:false,reason:'Launch deck is preparing. See the inspector countdown.'};const type=base.mode,key=type==='fighter'?'fighters':'bombers';if(base[key]<=0)return {ok:false,reason:`No ${type}s aboard.`};const p={x,y};if(distance(base,p)>TYPES[type].fuel)return {ok:false,reason:'Destination beyond aircraft fuel range.'};base[key]--;base.cooldown=120;const u=this.add(type,base.team,base.x,base.y,{homeId:base.id});u.heading=Math.atan2(y-base.y,longitudeDelta(base.x,x));if(type==='bomber'){u.ammo=base.stockNukes>0?1:0;if(u.ammo)base.stockNukes--;u.mode='naval';}this.moveUnit(u,p);this.event(`${type==='fighter'?'Fighter':'Bomber'} ${u.id} launched from ${TYPES[base.type].name.toLowerCase()} ${base.id}.`);this.onEffect('aircraft');return {ok:true,unit:u};}
